function renderImageFields(){const host=workDialog.querySelector('#imageWorkbenchFields');host.innerHTML='<div class="directorGrid">'+[['cityDuration','Duration (s)'],['cityFlyTime','Camera move time (s)'],['cityStartDistance','Start zoom distance'],['cityEndDistance','End zoom distance'],['cityStartElevation','Start tilt (°)'],['cityEndElevation','End tilt (°)'],['cityRoll','Start roll (°)'],['cityEndRoll','End roll (°)'],['cityHeading','Heading (°)'],['cityTurns','Camera turns'],['cityEdgeBlur','Edge blur (px)']].map(([k,label])=>`<label>${label}<input type="number" step=".1" data-work="${k}" value="${workMotion[k]}"></label>`).join('')+'</div><div class="studioActions"><button class="pill" id="workStartFocus">Pick start focus</button><button class="pill" id="workEndFocus">Pick end focus</button><button class="pill" id="workTrace">Trace color spot</button><button class="pill" id="workFinishTrace">Finish trace</button></div><label>New region color<input id="workRegionColor" type="color" value="#7551c7"></label><div class="directorGrid"><button class="pill" id="workAddSplit">Add two-color division</button><button class="pill" id="workClearRegions">Clear regions</button></div><div id="workRegionFields"></div><button class="primary wide" id="saveImageClip">'+(workClip?'Update animated image scene':'Add animated image scene to sequence')+'</button><button class="pill wide" id="saveImageMotion">Download motion recipe JSON</button>';host.querySelectorAll('[data-work]').forEach(el=>el.oninput=()=>{workMotion[el.dataset.work]=+el.value;if(el.dataset.work==='cityDuration')workMotion.cityFlyTime=Math.min(workMotion.cityFlyTime,+el.value);workKey=''});for(const [id,pick]of [['workStartFocus','start'],['workEndFocus','end'],['workTrace','trace']])host.querySelector('#'+id).onclick=()=>{workPick=pick;workPoints=[];workPlaying=false;workDialog.querySelector('#imageWorkbenchHelp').textContent=pick==='trace'?'Tap around the spot, then Finish trace.':'Tap your focus point in the image.'};host.querySelector('#workFinishTrace').onclick=()=>{if(workPoints.length>=3){workMotion.cityRegions.push({color:host.querySelector('#workRegionColor').value,opacity:.35,blend:'color',start:0,fade:.1,points:workPoints.map(p=>p.uv)});workPick=null;workPoints=[];workKey='';renderWorkRegions()}};host.querySelector('#workAddSplit').onclick=()=>{workMotion.cityRegions.push({type:'split',side:'left',position:.5,angle:0,curve:0,color:'#277eb3',opacity:.35,start:0,fade:.1},{type:'split',side:'right',position:.5,angle:0,curve:0,color:'#cc4b43',opacity:.35,start:0,fade:.1});renderWorkRegions();workKey=''};host.querySelector('#workClearRegions').onclick=()=>{workMotion.cityRegions=[];renderWorkRegions();workKey=''};host.querySelector('#saveImageClip').onclick=()=>{const clip={id:workClip||'image-clip-'+Date.now(),assetId:workAsset,duration:Math.max(1,workMotion.cityDuration),motion:structuredClone(workMotion),method:'image-on-3d-plane'};const i=fx.imageClips.findIndex(c=>c.id===clip.id);if(i>=0)fx.imageClips[i]=clip;else fx.imageClips.push(clip);workClip=clip.id;saveEffects();syncDuration();host.querySelector('#saveImageClip').textContent='Saved to sequence'};host.querySelector('#saveImageMotion').onclick=()=>downloadData({schemaVersion:1,assetId:workAsset,method:'image-on-3d-plane',motion:workMotion},'image-motion.json');renderWorkRegions()}
