function workTick(now){if(!workDialog.open)return;const dt=workLast?Math.min(.1,(now-workLast)/1000):0;workLast=now;if(workPlaying){workTime=Math.min(workMotion.cityDuration,workTime+dt);if(workTime>=workMotion.cityDuration)workPlaying=false}const media=getStudioMedia(workAsset),key=workTime+JSON.stringify(workMotion)+workPoints.length+(media instanceof HTMLVideoElement?media.readyState:media?.naturalWidth);if(key!==workKey&&mediaIsReady(media)){workKey=key;if(media instanceof HTMLVideoElement){const desired=workTime%Math.max(.1,media.duration||10);if(!media.seeking&&Math.abs(media.currentTime-desired)>.2)media.currentTime=desired;if(workPlaying)media.play().catch(()=>{});else media.pause()}wctx.fillStyle='#08131c';wctx.fillRect(0,0,960,540);paintStudioMediaEffects(wctx,media,workTime,()=>cityEngine.paint(wctx,workTime,workMotion,media));softEdgeBlur(wctx,workMotion.cityEdgeBlur);wctx.fillStyle='#e9d7ff';for(const p of workPoints){wctx.beginPath();wctx.arc(p.x,p.y,4,0,Math.PI*2);wctx.fill()}}const slider=workDialog.querySelector('#imageWorkbenchTime');slider.max=workMotion.cityDuration;slider.value=workTime;requestAnimationFrame(workTick)}
