let storyContext=null;try{storyContext=JSON.parse(localStorage.getItem('motion-story-context')||'null')}catch{}
function mergeStoryEvidence(current,incoming){if(!current)return structuredClone(incoming);if(!String(current.transcript||'').trim()&&incoming.transcript){current.transcript=incoming.transcript;current.transcriptStatus=incoming.transcriptStatus;}if(String(current.notes||'').includes('No transcript, audio interpretation')&&incoming.notes)current.notes=incoming.notes;current.transcriptSources??=[];for(const source of incoming.transcriptSources||[])if(!current.transcriptSources.some(s=>s.sha256===source.sha256))current.transcriptSources.push(structuredClone(source));if(/^review-v\d+-01m45-current$/.test(current.editorialContext?.id||'')&&/^review-v\d+-01m45-current$/.test(incoming.editorialContext?.id||'')&&Number(current.editorialContext.id.match(/v(\d+)/)[1])<Number(incoming.editorialContext.id.match(/v(\d+)/)[1])){current.sourceContextHistory??=[];current.sourceContextHistory.push({editorialContext:structuredClone(current.editorialContext),shots:structuredClone((current.shots||[]).filter(s=>['history-v46-shoe-strip','history-v46-shoe-turn','history-v46-photo-flip','history-v46-photo-card','history-v46-over-shoulder','history-v46-workshop','history-v46-ruins-wide','history-v46-ruins-close','history-v46-portrait-mono','history-v46-portrait-dissolve','history-v46-portrait-color','history-v46-dark-exit','history-v46-ruined-street','history-v46-ruin-occlusion','history-v46-salvage-search','history-v46-cable-focus','history-v46-salvage-overview','history-v46-vertical-workshop-passage','history-v46-wheel-trimmer','history-v46-shoe-walk-handoff','history-v46-shoe-magnifier','history-v46-shoe-evolution','history-v46-next-occlusion'].includes(s.id)))});for(const old of current.shots||[]){if(!['history-v46-shoe-strip','history-v46-shoe-turn','history-v46-photo-flip','history-v46-photo-card','history-v46-over-shoulder','history-v46-workshop','history-v46-ruins-wide','history-v46-ruins-close','history-v46-portrait-mono','history-v46-portrait-dissolve','history-v46-portrait-color','history-v46-dark-exit','history-v46-ruined-street','history-v46-ruin-occlusion','history-v46-salvage-search','history-v46-cable-focus','history-v46-salvage-overview','history-v46-vertical-workshop-passage','history-v46-wheel-trimmer','history-v46-shoe-walk-handoff','history-v46-shoe-magnifier','history-v46-shoe-evolution','history-v46-next-occlusion'].includes(old.id))continue;const next=(incoming.shots||[]).find(s=>s.id===old.id);if(next){old.assets=structuredClone(next.assets);old.actions=structuredClone(next.actions);old.editorialContext=structuredClone(next.editorialContext);old.retainedAlternative=next.retainedAlternative;}}current.editorialContext=structuredClone(incoming.editorialContext);}if(!current.editorialContext&&incoming.editorialContext)current.editorialContext=structuredClone(incoming.editorialContext);for(const key of ['shots','assets']){current[key]??=[];for(const item of incoming[key]||[]){const old=current[key].find(o=>(o.id||o.assetId)===(item.id||item.assetId));if(!old){current[key].push(structuredClone(item));continue;}if(key==='shots'){if(!String(old.narration||'').trim()&&item.narration){old.narration=item.narration;old.narrationStatus=item.narrationStatus;}if(!old.editorialContext&&item.editorialContext)old.editorialContext=structuredClone(item.editorialContext);}}}return current;}
fetch('semantic-context.json?v=transcript-v60').then(r=>r.json()).then(data=>{storyContext=mergeStoryEvidence(storyContext,data);});
const storyButton=document.createElement('button');storyButton.className='pill';storyButton.id='openStoryContext';storyButton.textContent='Story & prompts';document.querySelector('#openAssets').before(storyButton);
const storyDialog=document.createElement('dialog');storyDialog.className='studioDialog';storyDialog.innerHTML='<div class="studioHead"><h2>Story context & asset prompts</h2><button class="pill" id="closeStoryContext">Done</button></div><p class="sub">Associate narration with visuals, movement and sound. The timestamped source transcript is attached. Scene alignment and editorial interpretations remain provisional. Reconstructed prompts are labelled; no historical prompt is presented as exact.</p><p class="sub"><a href="context/README.md" target="_blank">Attached original transcript and AI context</a> · <a href="context/editorial-context.md" target="_blank">Scene purposes and review notes</a></p><label>Full transcript<textarea id="storyTranscript" rows="5"></textarea></label><label>Shot / sequence<select id="storyShot"></select></label><div id="storyFields"></div><label>Asset prompt record<select id="storyAsset"></select></label><div id="storyAssetFields"></div><button class="primary" id="exportStoryContext">Export context JSON</button><a class="pill" href="AUTHORING-ROADMAP.md" target="_blank">Authoring roadmap</a>';document.body.append(storyDialog);
function saveStoryContext(){localStorage.setItem('motion-story-context',JSON.stringify(storyContext))}
function storyField(host,target,key,label){const l=document.createElement('label');l.textContent=label;const input=document.createElement('textarea');input.rows=3;input.value=target[key]||'';input.dataset.story=key;input.oninput=()=>{target[key]=input.value;saveStoryContext()};l.append(input);host.append(l)}
function showStoryShot(){const host=storyDialog.querySelector('#storyFields');host.innerHTML='';const shot=storyContext.shots[+storyDialog.querySelector('#storyShot').value];if(!shot)return;const p=document.createElement('p');p.className='sub';p.textContent=`${shot.scene} · local ${shot.localStart}–${shot.localEnd}s · assets: ${shot.assets.join(', ')}`;host.append(p);for(const [k,label]of [['narration','Associated narration'],['intent','Communication goal'],['metaphor','Text ↔ image / motion association'],['soundCue','Planned sound cue'],['status','Review status']])storyField(host,shot,k,label)}
function showStoryAsset(){const host=storyDialog.querySelector('#storyAssetFields');host.innerHTML='';const a=storyContext.assets[+storyDialog.querySelector('#storyAsset').value];if(!a)return;for(const [k,label]of [['generationPrompt','Asset prompt'],['promptStatus','Prompt provenance / exactness'],['method','Production method'],['rationale','Concise creative rationale']])storyField(host,a,k,label)}
storyButton.onclick=()=>{if(!storyContext)return;playing=false;storyDialog.querySelector('#storyTranscript').value=storyContext.transcript;for(const [id,items,label]of [['storyShot',storyContext.shots,'id'],['storyAsset',storyContext.assets,'assetId']]){const select=storyDialog.querySelector('#'+id);select.innerHTML='';items.forEach((item,i)=>{const o=document.createElement('option');o.value=i;o.textContent=item[label];select.append(o)})}showStoryShot();showStoryAsset();storyDialog.showModal()};storyDialog.querySelector('#storyShot').onchange=showStoryShot;storyDialog.querySelector('#storyAsset').onchange=showStoryAsset;storyDialog.querySelector('#storyTranscript').oninput=e=>{storyContext.transcript=e.target.value;storyContext.transcriptStatus=e.target.value.trim()?'provided; alignment pending':'awaiting-user-transcript';saveStoryContext()};storyDialog.querySelector('#closeStoryContext').onclick=()=>storyDialog.close();storyDialog.querySelector('#exportStoryContext').onclick=()=>downloadData(storyContext,'story-context.json');
